//! Exports the TypeScript bindings into a directory: one file per type and an `index.ts`.

use std::{
    fmt::Write as _,
    fs, io,
    path::{Path, PathBuf},
};

use se_domain::{FormatPreset, Project, Violation};
use se_protocol::{ClientMessage, CoreHandshake, ServerMessage};
use ts_rs::{Config, TS};

/// First lines of every generated file, replacing the ts-rs note.
pub const HEADER: &str = "// GENERATED — DO NOT EDIT. Source: Rust types deriving `ts_rs::TS` (crates/se-protocol,\n// crates/se-domain). Regenerate with `pnpm codegen`.\n";

/// Start of the note ts-rs writes on the first line of each file.
const TS_RS_NOTE_PREFIX: &str = "// This file was generated by [ts-rs]";

/// Name of the barrel file re-exporting every generated type.
const INDEX_FILE: &str = "index.ts";

/// TypeScript type of `i64`/`u64`: flicks and ids travel as JSON numbers (ADR-0004), exact up to
/// ±2^53, so they must not become `bigint`.
const LARGE_INT_TYPE: &str = "number";

/// Why the bindings could not be generated.
#[derive(Debug, thiserror::Error)]
pub enum CodegenError {
    /// ts-rs merges into existing files, so a non-empty directory could keep stale types.
    #[error("the output directory {0} must be empty or absent")]
    OutputNotEmpty(PathBuf),
    /// ts-rs failed to export a root type or one of its dependencies.
    #[error("cannot export {type_name} to TypeScript: {source}")]
    Export {
        /// Rust name of the root type.
        type_name: &'static str,
        /// The ts-rs error.
        source: ts_rs::ExportError,
    },
    /// A file or directory could not be read or written.
    #[error("cannot access {path}: {source}")]
    Io {
        /// The file or directory.
        path: PathBuf,
        /// The underlying error.
        source: io::Error,
    },
    /// ts-rs changed its output format: the header replacement must be updated.
    #[error("{0} does not start with the ts-rs note; update se-codegen for this ts-rs version")]
    UnexpectedHeader(PathBuf),
}

/// Generates the bindings into `output_dir` and returns the generated type files (relative paths
/// with `/` separators, sorted), not counting `index.ts`.
pub fn generate(output_dir: &Path) -> Result<Vec<String>, CodegenError> {
    ensure_empty(output_dir)?;
    let config = Config::new()
        .with_out_dir(output_dir)
        .with_large_int(LARGE_INT_TYPE);
    export_roots(&config)?;
    let files = typescript_files(output_dir)?;
    for file in &files {
        replace_header(&output_dir.join(file))?;
    }
    write_index(output_dir, &files)?;
    Ok(files)
}

/// Exports the root types together with every type they reference.
///
/// Commands, results, events and errors are reachable from the message envelopes, so adding one
/// needs no change here. Add a root only for a type no envelope references: the document model
/// (`Project` and everything inside it), validation violations and format presets are roots until
/// protocol commands carry them.
fn export_roots(config: &Config) -> Result<(), CodegenError> {
    export_all::<ClientMessage>(config)?;
    export_all::<ServerMessage>(config)?;
    export_all::<CoreHandshake>(config)?;
    export_all::<Project>(config)?;
    export_all::<Violation>(config)?;
    export_all::<FormatPreset>(config)
}

fn export_all<T: TS + 'static>(config: &Config) -> Result<(), CodegenError> {
    T::export_all(config).map_err(|source| CodegenError::Export {
        type_name: std::any::type_name::<T>(),
        source,
    })
}

fn ensure_empty(dir: &Path) -> Result<(), CodegenError> {
    match fs::read_dir(dir) {
        Ok(mut entries) => match entries.next() {
            Some(_) => Err(CodegenError::OutputNotEmpty(dir.to_path_buf())),
            None => Ok(()),
        },
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(source) => Err(io_error(dir, source)),
    }
}

/// Every `.ts` file under `root`, as sorted relative paths with `/` separators.
fn typescript_files(root: &Path) -> Result<Vec<String>, CodegenError> {
    let mut files = Vec::new();
    collect_typescript_files(root, "", &mut files)?;
    files.sort();
    Ok(files)
}

fn collect_typescript_files(
    dir: &Path,
    prefix: &str,
    files: &mut Vec<String>,
) -> Result<(), CodegenError> {
    let entries = fs::read_dir(dir).map_err(|source| io_error(dir, source))?;
    for entry in entries {
        let entry = entry.map_err(|source| io_error(dir, source))?;
        let name = entry.file_name().to_string_lossy().into_owned();
        let relative = format!("{prefix}{name}");
        let path = entry.path();
        if path.is_dir() {
            collect_typescript_files(&path, &format!("{relative}/"), files)?;
        } else if Path::new(&name)
            .extension()
            .is_some_and(|extension| extension == "ts")
        {
            files.push(relative);
        }
    }
    Ok(())
}

fn replace_header(path: &Path) -> Result<(), CodegenError> {
    let contents = fs::read_to_string(path).map_err(|source| io_error(path, source))?;
    let Some((note, rest)) = contents.split_once('\n') else {
        return Err(CodegenError::UnexpectedHeader(path.to_path_buf()));
    };
    if !note.starts_with(TS_RS_NOTE_PREFIX) {
        return Err(CodegenError::UnexpectedHeader(path.to_path_buf()));
    }
    fs::write(path, format!("{HEADER}{rest}")).map_err(|source| io_error(path, source))
}

fn write_index(output_dir: &Path, files: &[String]) -> Result<(), CodegenError> {
    let mut index = String::from(HEADER);
    for file in files {
        let module = file.trim_end_matches(".ts");
        // Writing to a `String` cannot fail.
        let _ = writeln!(index, "export type * from './{module}';");
    }
    let path = output_dir.join(INDEX_FILE);
    fs::write(&path, index).map_err(|source| io_error(&path, source))
}

fn io_error(path: &Path, source: io::Error) -> CodegenError {
    CodegenError::Io {
        path: path.to_path_buf(),
        source,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generates_one_file_per_type_with_the_header_and_an_index() {
        let scratch = tempfile::tempdir().unwrap();
        let output = scratch.path().join("generated");

        let files = generate(&output).unwrap();

        for expected in [
            "ClientMessage.ts",
            "Command.ts",
            "CoreEvent.ts",
            "ErrorCode.ts",
            "Project.ts",
            "ItemKind.ts",
            "Violation.ts",
            "FormatPreset.ts",
        ] {
            assert!(
                files.iter().any(|file| file == expected),
                "{expected} missing"
            );
        }
        for file in &files {
            let contents = fs::read_to_string(output.join(file)).unwrap();
            assert!(contents.starts_with(HEADER), "{file} lacks the header");
        }
        let index = fs::read_to_string(output.join(INDEX_FILE)).unwrap();
        assert!(index.starts_with(HEADER));
        assert!(index.contains("export type * from './ServerMessage';\n"));
    }

    #[test]
    fn large_integers_become_numbers() {
        let scratch = tempfile::tempdir().unwrap();
        generate(scratch.path()).unwrap();
        let envelope = fs::read_to_string(scratch.path().join("RequestEnvelope.ts")).unwrap();
        assert!(envelope.contains("id: number"), "{envelope}");
        assert!(!envelope.contains("bigint"));
    }

    #[test]
    fn flicks_are_a_branded_number_and_ids_are_strings() {
        let scratch = tempfile::tempdir().unwrap();
        generate(scratch.path()).unwrap();
        let flicks = fs::read_to_string(scratch.path().join("Flicks.ts")).unwrap();
        assert!(
            flicks.contains("export type Flicks = number & { readonly __brand: 'Flicks' };"),
            "{flicks}"
        );
        let item_id = fs::read_to_string(scratch.path().join("ItemId.ts")).unwrap();
        assert!(
            item_id.contains("export type ItemId = string;"),
            "{item_id}"
        );
    }

    #[test]
    fn generating_twice_gives_identical_output() {
        let first = tempfile::tempdir().unwrap();
        let second = tempfile::tempdir().unwrap();
        let files = generate(first.path()).unwrap();
        assert_eq!(generate(second.path()).unwrap(), files);
        for file in files.iter().map(String::as_str).chain([INDEX_FILE]) {
            assert_eq!(
                fs::read_to_string(first.path().join(file)).unwrap(),
                fs::read_to_string(second.path().join(file)).unwrap(),
                "{file} differs between runs"
            );
        }
    }

    #[test]
    fn refuses_a_non_empty_output_directory() {
        let scratch = tempfile::tempdir().unwrap();
        fs::write(scratch.path().join("Stale.ts"), "export type Stale = 1;\n").unwrap();
        assert!(matches!(
            generate(scratch.path()),
            Err(CodegenError::OutputNotEmpty(_))
        ));
    }
}
